import { randomUUID } from 'node:crypto';
import { createReadStream, promises as fs } from 'node:fs';
import { dirname, join, resolve, sep } from 'node:path';
import type { Readable } from 'node:stream';
import { Injectable } from '@nestjs/common';
import { AppConfigService } from '../../config/app-config.service';

/** Storage keys are generated by us and look exactly like this; anything else is never read from disk. */
export const STORAGE_KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp|pdf)$/;

export function newStorageKey(ext: string): string {
  return `${randomUUID()}.${ext}`;
}

/**
 * Where the bytes live. The rest of the application only knows this interface, so a cloud provider (S3, R2,
 * Cloudinary …) can replace the local disk by providing another implementation in MediaModule.
 */
export abstract class MediaStorage {
  abstract put(key: string, data: Buffer): Promise<void>;
  abstract open(key: string): Promise<Readable>;
  abstract remove(key: string): Promise<void>;
}

@Injectable()
export class LocalMediaStorage extends MediaStorage {
  private readonly root: string;

  constructor(config: AppConfigService) {
    super();
    this.root = resolve(config.get('MEDIA_DIR'));
  }

  /** The absolute path for a key, refusing anything that is not one of our generated keys (no traversal possible). */
  private pathFor(key: string): string {
    if (!STORAGE_KEY.test(key)) throw new Error('Invalid storage key');
    const full = resolve(join(this.root, key));
    if (!full.startsWith(this.root + sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.pathFor(key);
    await fs.mkdir(dirname(file), { recursive: true });
    // 'wx': never overwrite an existing file
    await fs.writeFile(file, data, { flag: 'wx', mode: 0o640 });
  }

  async open(key: string): Promise<Readable> {
    const file = this.pathFor(key);
    await fs.access(file);
    return createReadStream(file);
  }

  async remove(key: string): Promise<void> {
    await fs.rm(this.pathFor(key), { force: true });
  }
}
